SELECT DATE_FORMAT(created_at,'%Y-%m-%d %H:00') AS raw_hour, COUNT(*) AS n, ROUND(AVG(TIMESTAMPDIFF(MICROSECOND, observed_at, created_at))/1000,1) AS avg_ms, ROUND(MIN(TIMESTAMPDIFF(MICROSECOND, observed_at, created_at))/1000,1) AS min_ms, ROUND(MAX(TIMESTAMPDIFF(MICROSECOND, observed_at, created_at))/1000,1) AS max_ms FROM market_price_event WHERE id BETWEEN 1330000 AND 1580000 AND source='BINANCE_KLINE_DIRECT_FIX153' GROUP BY raw_hour ORDER BY raw_hour